"about_items": [
{
"n": "#20·32",
"text": "A beige mini dress featuring a high neck with a delicate tie closure and voluminous puff sleeves. It has a fitted bodice that flows into a flared skirt, creating a soft and feminine line."
},
{
"n": "#167·20",
"text": "A light grey cardigan knitted in an open, airy pattern with delicate cutouts along the shoulders and sleeves. It features long, slightly puffed sleeves and comes with a matching white belt to cinch the waist."
},
{
"n": "#426·16",
"text": "An elegant graphite headband adorned with a large bow made of satin ribbon and clusters of black and silver crystals that add a touch of sparkle to your hairstyle."
},
{
"n": "#198·07",
"text": "Beige woven leather ballet flats designed as slingbacks with an ankle strap and buckle. They feature a pointed toe and a braided texture across the vamp for a comfortable yet stylish finish."
},
{
"n": "#291·07",
"text": "A structured tote bag made of natural canvas fabric with bold orange leather accents on the handles and side buckles. The front displays large grey lettering that adds an artistic touch to this everyday essential."
}
]
}
